from collections import defaultdict,Counter

def axis_stats(a):
    res=[]
    for typ in ('diff','sum'):
        groups=defaultdict(Counter)
        for r,row in enumerate(a):
            for c,v in enumerate(row):
                if v:
                    k=c-r if typ=='diff' else c+r
                    groups[k][v]+=1
        score=sum(max(ct.values())**2 for ct in groups.values())
        consistent=sum(max(ct.values()) for ct in groups.values())
        res.append((typ,score,consistent,len(groups),[(k,ct) for k,ct in groups.items()]))
    return res
